import { readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

import { parse as parseYaml, stringify as stringifyYaml } from "yaml";

import { invalidEvalsDir } from "../../errors";
import { TASKS_DIR } from "./datasets";
import { STATE_FILE } from "./pack";
import { byteOrder, type TaskHashes } from "./tasks";

/** `<dataset>/lmnr.lock`: the dataset version the repo pins. Committed. */
export const LOCKFILE = "lmnr.lock";
const LOCK_HEADER =
  "# Generated by lmnr-cli (eval push / eval pull). Commit it; don't edit by hand.\n";
const HASH = /^sha256:[0-9a-f]{64}$/;
/** What `.gitignore` gets once the dataset's tasks live in Laminar. */
const GITIGNORE_ENTRY = `/${TASKS_DIR}/`;

/**
 * A dataset version's tasks: the lockfile, and the sync state (what `tasks/`
 * was last pulled or pushed as) have this shape.
 */
export interface DatasetLock {
  dataset: string;
  version: number;
  tasks: TaskHashes;
}

/** `tasks` sorted by name, in UTF-8 byte order. */
export const sortedTasks = (tasks: TaskHashes): [string, string][] =>
  Object.entries(tasks).sort(([a], [b]) => byteOrder(a, b));

export const sameTasks = (a: TaskHashes, b: TaskHashes): boolean => {
  const keys = Object.keys(a);
  return (
    keys.length === Object.keys(b).length && keys.every((k) => a[k] === b[k])
  );
};

/** How `to` differs from `from`, each list sorted. */
export interface TaskDiff {
  added: string[];
  modified: string[];
  removed: string[];
}

export const diffTasks = (from: TaskHashes, to: TaskHashes): TaskDiff => {
  const sort = (names: string[]) => names.sort(byteOrder);
  return {
    added: sort(Object.keys(to).filter((k) => !(k in from))),
    modified: sort(
      Object.keys(to).filter((k) => k in from && from[k] !== to[k]),
    ),
    removed: sort(Object.keys(from).filter((k) => !(k in to))),
  };
};

/** A parsed lockfile or state, or the reason it isn't one. */
const parseLock = (value: unknown): DatasetLock | string => {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return "not a mapping";
  }
  const { dataset, version, tasks } = value as Record<string, unknown>;
  if (typeof dataset !== "string" || !dataset) return "`dataset` is missing";
  if (
    typeof version !== "number" ||
    !Number.isInteger(version) ||
    version < 1
  ) {
    return "`version` is not a positive integer";
  }
  if (typeof tasks !== "object" || tasks === null || Array.isArray(tasks)) {
    return "`tasks` is not a mapping";
  }
  for (const [name, hash] of Object.entries(tasks)) {
    if (typeof hash !== "string" || !HASH.test(hash)) {
      return `task ${name} has no valid hash`;
    }
  }
  return { dataset, version, tasks: tasks as TaskHashes };
};

/** The dataset's lockfile; null when it has none. Malformed → `invalid_evals_dir`. */
export const readLock = async (
  datasetDir: string,
): Promise<DatasetLock | null> => {
  const file = path.join(datasetDir, LOCKFILE);
  const text = await readFile(file, "utf8").catch(() => null);
  if (text === null) return null;
  let parsed: DatasetLock | string;
  try {
    parsed = parseLock(parseYaml(text));
  } catch (error) {
    parsed = String(error);
  }
  if (typeof parsed === "string") {
    throw invalidEvalsDir(
      `${file} is not a valid lockfile (${parsed}). Restore it from git, or ` +
        "delete it and run `lmnr-cli eval pull --version <n>`.",
    );
  }
  return parsed;
};

/** Write through a temp file, so an interrupted write never leaves half a file. */
const writeAtomic = async (file: string, content: string) => {
  const tmp = `${file}.${process.pid}.tmp`;
  await writeFile(tmp, content);
  await rename(tmp, file);
};

export const formatLock = (lock: DatasetLock): string =>
  LOCK_HEADER +
  stringifyYaml(
    new Map<string, unknown>([
      ["dataset", lock.dataset],
      ["version", lock.version],
      ["tasks", new Map(sortedTasks(lock.tasks))],
    ]),
  );

export const writeLock = (datasetDir: string, lock: DatasetLock) =>
  writeAtomic(path.join(datasetDir, LOCKFILE), formatLock(lock));

const statePath = (datasetDir: string) =>
  path.join(datasetDir, TASKS_DIR, STATE_FILE);

/**
 * The sync state: the version `tasks/` was last synced to, plus `localHashes`,
 * what synced tasks hash to on THIS disk where that differs from their hash
 * (Windows has no exec bits, so it hashes modes by extension). A task whose
 * disk hash is its `localHashes` entry is unchanged since the sync.
 */
export interface TasksState extends DatasetLock {
  localHashes: TaskHashes;
}

/**
 * What `tasks/` was last synced to (pulled or pushed). Null when unknown: never
 * synced, or the file is unreadable (then `tasks/` counts as locally changed
 * unless it matches the lockfile).
 */
export const readState = async (
  datasetDir: string,
): Promise<TasksState | null> => {
  try {
    const value = JSON.parse(await readFile(statePath(datasetDir), "utf8"));
    const parsed = parseLock(value);
    if (typeof parsed === "string") return null;
    const localHashes: TaskHashes = {};
    for (const [name, hash] of Object.entries(value.localHashes ?? {})) {
      if (typeof hash === "string" && HASH.test(hash) && name in parsed.tasks) {
        localHashes[name] = hash;
      }
    }
    return { ...parsed, localHashes };
  } catch {
    return null;
  }
};

/**
 * Record that `tasks/` holds `state`. `disk` is what those tasks hash to on
 * this disk (`hashLocalTasks`); entries that differ become `localHashes`.
 */
export const writeState = (
  datasetDir: string,
  state: DatasetLock,
  disk: TaskHashes = state.tasks,
) => {
  const localHashes = sortedTasks(disk).filter(
    ([name, hash]) => name in state.tasks && state.tasks[name] !== hash,
  );
  return writeAtomic(
    statePath(datasetDir),
    `${JSON.stringify(
      {
        dataset: state.dataset,
        version: state.version,
        tasks: Object.fromEntries(sortedTasks(state.tasks)),
        ...(localHashes.length > 0
          ? { localHashes: Object.fromEntries(localHashes) }
          : {}),
      },
      null,
      2,
    )}\n`,
  );
};

const IGNORES_TASKS = new Set([
  TASKS_DIR,
  `${TASKS_DIR}/`,
  `/${TASKS_DIR}`,
  `/${TASKS_DIR}/`,
]);

/**
 * Make `<dataset>/.gitignore` ignore `tasks/`: once a dataset is versioned its
 * tasks live in Laminar, and the lockfile pins them. Returns whether it changed.
 */
export const ensureGitignore = async (datasetDir: string): Promise<boolean> => {
  const file = path.join(datasetDir, ".gitignore");
  const text = (await readFile(file, "utf8").catch(() => null)) ?? "";
  if (text.split(/\r?\n/).some((line) => IGNORES_TASKS.has(line.trim()))) {
    return false;
  }
  const sep = text && !text.endsWith("\n") ? "\n" : "";
  await writeFile(file, `${text}${sep}${GITIGNORE_ENTRY}\n`);
  return true;
};
